begin;
select plan(26);
select has_function('public','concierge_care_command_v1',array['jsonb'],'fixed care entry exists');
select ok(has_function_privilege('authenticated','public.concierge_care_command_v1(jsonb)','execute') and not has_function_privilege('anon','public.concierge_care_command_v1(jsonb)','execute') and not has_function_privilege('service_role','public.concierge_care_command_v1(jsonb)','execute'),'care entry least privilege');
select is((select count(*)::integer from jsonb_object_keys(concierge.care_command_fields())),13,'care dispatcher closed13');
select is((select count(*)::integer from jsonb_object_keys(concierge.plan_command_fields())),26,'old24 plus two dependency actions');
select is(jsonb_array_length(concierge.plan_command_fields()->'grant_task_v1'->'actions'->'item'->'values'),14,'old finite task grant unchanged');
select ok(not(concierge.plan_command_fields()->'grant_task_v1'->'actions'->'item'->'values' ? 'read_draft_dependencies_v1'),'no implicit care/dependency task read');
select is((concierge.care_command_fields()->'read_use_history_v1'->'limit'->>'max')::integer,100,'history page item bound');
select is((concierge.care_command_fields()->'read_use_history_v1'->'limit'->>'min')::integer,1,'history page min bound');
select is((concierge.care_command_fields()->'report_unreviewed_product_v1'->'product'->'fields'->'name'->>'max')::integer,200,'descriptor name bound');
select is((concierge.care_command_fields()->'report_unreviewed_product_v1'->'product'->'fields'->'labelPhotoIds'->>'max')::integer,100,'label IDs bound');
select ok(not(concierge.care_command_fields()->'report_product_use_v1'->'change'->'variants'->0->'fields' ? 'startedOn'),'single occurrence date source');
select throws_ok($$select public.concierge_care_command_v1('{"schemaVersion":1,"action":"read_use_history_v1","product":null,"cursor":null,"limit":null}')$$,'P0001','concierge_invalid_input','SQL NULL page bound rejects');
select throws_ok($$select public.concierge_care_command_v1('{"schemaVersion":1,"action":"read_use_history_v1","product":null,"cursor":null,"limit":101}')$$,'P0001','concierge_invalid_input','SQL oversized page bound rejects');
select throws_ok($$select public.concierge_care_command_v1('{"schemaVersion":1,"action":"read_client_plan_v2","version":null,"clientId":"10000000-0000-4000-8000-000000000001"}')$$,'P0001','concierge_invalid_input','owner-derived read rejects selector');
select throws_ok($$select public.concierge_care_command_v1('{"schemaVersion":1,"action":"arbitrary_sql"}')$$,'P0001','concierge_invalid_input','unknown action rejects');
select is((select count(*)::integer from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='concierge' and c.relkind='r' and (c.relname like 'care_%' or c.relname='plan_draft_dependency_bases') and not c.relrowsecurity),0,'all care tables RLS');
select is((select count(*)::integer from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='concierge' and c.relkind='r' and (c.relname like 'care_%' or c.relname='plan_draft_dependency_bases') and (has_table_privilege('anon',c.oid,'select,insert,update,delete') or has_table_privilege('authenticated',c.oid,'select,insert,update,delete') or has_table_privilege('service_role',c.oid,'select,insert,update,delete'))),0,'no raw care ACL');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='concierge' and (p.proname like 'care_%' or p.proname like 'plan_%') and (has_function_privilege('anon',p.oid,'execute') or has_function_privilege('authenticated',p.oid,'execute') or has_function_privilege('service_role',p.oid,'execute'))),0,'no private helper/base EXECUTE');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='concierge' and (p.proname like 'care_%' or p.proname like 'plan_%') and not coalesce(p.proconfig @> array['search_path=""'],false)),0,'pinned empty search paths');
select is(concierge.plan_dependency_basis_v2(null)->'legacyBasis',jsonb_build_object('publicationVersion',null,'useRevision',0),'private dependencies preserve strict legacy basis');
select is(concierge.plan_basis(null)->'useRevision','0'::jsonb,'legacy activation maximum preserved');
select ok(exists(select 1 from pg_indexes where schemaname='concierge' and indexname='plan_original_publication_event' and indexdef like '%WHERE%'),'publication uniqueness stays partial and retained');
select ok(exists(select 1 from pg_indexes where schemaname='concierge' and indexname='plan_typed_source_event' and indexdef like '%source_id%'),'independent typed event uniqueness');
select isnt(concierge.care_cursor('10000000-0000-4000-8000-000000000001',1,'null',1,'10000000-0000-4000-8000-000000000003'),concierge.care_cursor('10000000-0000-4000-8000-000000000002',1,'null',1,'10000000-0000-4000-8000-000000000003'),'cursor binds owner');
select throws_ok($$select concierge.care_cursor_check(concierge.care_cursor('10000000-0000-4000-8000-000000000001',1,'null',1,'10000000-0000-4000-8000-000000000003'),'10000000-0000-4000-8000-000000000001',1,'null',2)$$,'P0001','concierge_cursor_conflict','changed head rejects stable cursor');
select ok(exists(select 1 from pg_trigger where tgname='care_publication_dependency_fence' and tgdeferrable and tginitdeferred) and exists(select 1 from pg_trigger where tgname='care_document_dependency_fence' and tgdeferrable and tginitdeferred),'both deferred output paths enforce dependency heads');
select * from finish();
rollback;
